import * as THREE from 'three';
import { OBJExporter } from 'three/examples/jsm/exporters/OBJExporter.js';
import { createScene } from './data/object.js';
import fs from 'fs';
import path from 'path';

// 1. Create the scene
const scene = createScene();

// 2. Helper to convert InstancedMesh to a Group of Meshes
function replaceInstancedMeshes(object) {
    const instancedMeshes = [];

    // Collect all InstancedMeshes
    object.traverse((child) => {
        if (child.isInstancedMesh) {
            instancedMeshes.push(child);
        }
    });

    // Process them
    instancedMeshes.forEach((im) => {
        const group = new THREE.Group();
        group.name = im.name;

        // Copy transform from InstancedMesh to Group
        group.position.copy(im.position);
        group.rotation.copy(im.rotation);
        group.scale.copy(im.scale);
        group.quaternion.copy(im.quaternion);

        // Note: matrixWorld will be updated later, but local transform is copied.

        const count = im.count;
        const geometry = im.geometry;
        const material = im.material;
        const matrix = new THREE.Matrix4();

        for (let i = 0; i < count; i++) {
            im.getMatrixAt(i, matrix);

            const mesh = new THREE.Mesh(geometry, material);
            mesh.name = `${im.name}_instance_${i}`;

            // Apply the instance matrix to the new mesh.
            // Since 'matrix' is the local transform of the instance relative to the InstancedMesh,
            // and our new 'group' has the same transform as the InstancedMesh,
            // we can just apply this matrix to the new mesh directly.

            // Decompose matrix to set pos/rot/scale
            matrix.decompose(mesh.position, mesh.quaternion, mesh.scale);

            group.add(mesh);
        }

        // Replace im with group in parent
        const parent = im.parent;
        if (parent) {
            parent.add(group);
            parent.remove(im);
        }
    });
}

// 3. Convert instances
replaceInstancedMeshes(scene);

// 4. Create a root for the rotation (Blender Z-up)
const exportRoot = new THREE.Group();
exportRoot.add(scene);

// Apply -90 degrees X rotation
exportRoot.rotation.x = -Math.PI / 2;

// Update all matrices to ensure world transforms are correct for the exporter
exportRoot.updateMatrixWorld(true);

// 5. Export
const exporter = new OBJExporter();
const objData = exporter.parse(exportRoot);

// 6. Write to file
const outputDir = '/root/output';
const outputPath = path.join(outputDir, 'object.obj');

if (!fs.existsSync(outputDir)){
    fs.mkdirSync(outputDir);
}

fs.writeFileSync(outputPath, objData);

console.log(`Exported object to ${outputPath}`);
